CREATE SCHEMA auth;CREATE SCHEMA extensions;CREATE EXTENSION pgcrypto SCHEMA extensions;
CREATE ROLE authenticated NOLOGIN;CREATE ROLE anon NOLOGIN;CREATE ROLE service_role NOLOGIN;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.uid',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.role',true),''),'authenticated') $$;
GRANT USAGE ON SCHEMA public,auth,extensions TO authenticated,service_role;
CREATE TABLE workspaces(id uuid PRIMARY KEY);
CREATE TABLE profiles(id uuid PRIMARY KEY,active_workspace_id uuid,full_name text);
CREATE TABLE workspace_members(workspace_id uuid,user_id uuid,status text DEFAULT 'active',role text DEFAULT 'member',PRIMARY KEY(workspace_id,user_id));
CREATE TABLE grants(user_id uuid,workspace_id uuid,key text,effect text);
CREATE TABLE permissions(key text PRIMARY KEY,module text,resource text,action text,scope text,label_pt text,description text,is_system boolean);
CREATE FUNCTION is_workspace_member(w uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=u AND status='active') $$;
CREATE FUNCTION user_has_permission(u uuid,w uuid,k text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT is_workspace_member(w,u) AND EXISTS(SELECT 1 FROM grants WHERE user_id=u AND workspace_id=w AND key=k AND effect='grant') AND NOT EXISTS(SELECT 1 FROM grants WHERE user_id=u AND workspace_id=w AND key=k AND effect='deny') $$;
CREATE FUNCTION is_read_only_view() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.readonly',true),''),'false')::boolean $$;
CREATE FUNCTION work_access_context() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT jsonb_build_object('workspace',active_workspace_id) FROM profiles WHERE id=auth.uid() $$;
CREATE TABLE deals(id uuid PRIMARY KEY,workspace_id uuid,deleted_at timestamptz);
CREATE TABLE proposals(id uuid PRIMARY KEY,workspace_id uuid,deal_id uuid,title text,status text,locked boolean DEFAULT false,decided_at timestamptz,version int DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE contract_draft_approvers(workspace_id uuid,user_id uuid);
CREATE TABLE contract_templates(id uuid PRIMARY KEY,workspace_id uuid,name text,body_html text,status text,is_default boolean);
CREATE TABLE contract_template_services(workspace_id uuid,template_id uuid,service_catalog_id uuid);
CREATE TABLE deal_line_items(workspace_id uuid,deal_id uuid,service_catalog_id uuid,created_at timestamptz DEFAULT now());
CREATE TABLE contract_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,deal_id uuid,proposal_id uuid,template_id uuid,title text,body_html text,status text DEFAULT 'pending_legal',missing_template boolean,created_by uuid,revision int DEFAULT 1,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),client_decided_at timestamptz);
CREATE UNIQUE INDEX draft_proposal ON contract_drafts(proposal_id) WHERE status NOT IN('rejected','canceled');
CREATE TABLE contract_draft_events(workspace_id uuid,draft_id uuid,actor_id uuid,kind text,detail jsonb);
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,owner_id uuid,user_id uuid,type text,title text,body text,link text,entity text,entity_id uuid,dedupe_key text UNIQUE);
CREATE TYPE contract_status AS ENUM('draft','in_review','in_negotiation','awaiting_signature','active','renewing','ended','terminated','canceled');
CREATE TYPE contract_approval_stage AS ENUM('purchasing','legal','finance');CREATE TYPE contract_approval_status AS ENUM('pending','approved','rejected');
CREATE TABLE contracts(id uuid PRIMARY KEY,workspace_id uuid,owner_id uuid,title text,role text DEFAULT 'provider',document_kind text DEFAULT 'main',status contract_status DEFAULT 'draft',proposal_id uuid,deal_id uuid,body_html text DEFAULT 'Versao atual',created_at timestamptz DEFAULT now());
CREATE TABLE contract_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,owner_id uuid,contract_id uuid,stage contract_approval_stage,sort_order int,status contract_approval_status,generation uuid,assigned_to uuid,superseded_at timestamptz,approver_id uuid,comment text,decided_at timestamptz,decided_by uuid);
CREATE TABLE contract_events(workspace_id uuid,contract_id uuid,actor_id uuid,event_type text,payload jsonb);
CREATE TABLE activities(id uuid PRIMARY KEY,workspace_id uuid,owner_id uuid,assigned_to uuid,created_by uuid,type text,subject text,body text,due_date timestamptz,completed boolean,task_status text,task_priority text,related_deal_id uuid,deleted_at timestamptz,remind_before_minutes int,reminder_sent_at timestamptz,wa_reminders_disabled boolean,external_ids jsonb);
ALTER TABLE activities ENABLE ROW LEVEL SECURITY;GRANT SELECT,INSERT,UPDATE,DELETE ON activities TO authenticated;
CREATE POLICY fixture_tasks ON activities FOR ALL TO authenticated USING(is_workspace_member(workspace_id,auth.uid())) WITH CHECK(is_workspace_member(workspace_id,auth.uid()));
CREATE TABLE esign_documents(id uuid PRIMARY KEY,workspace_id uuid,status text);
CREATE TABLE esign_signers(id uuid PRIMARY KEY,workspace_id uuid,document_id uuid,status text);
CREATE TABLE hiring_contract_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,contract_id uuid,kind text,document_id uuid,revoked_at timestamptz,contract_hash text);
CREATE TABLE contract_esign_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,document_id uuid,signer_id uuid,status text);
CREATE TABLE contract_forsign_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,contract_id uuid,contract_hash text,operation_id bigint,status text);
CREATE FUNCTION hiring_contract_fingerprint(i uuid) RETURNS text LANGUAGE sql STABLE AS $$ SELECT encode(extensions.digest(convert_to(body_html,'UTF8'),'sha256'),'hex') FROM contracts WHERE id=i $$;
CREATE FUNCTION sales_record_access(t text,i uuid,a text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM deals d JOIN profiles p ON p.id=auth.uid() WHERE d.id=i AND d.workspace_id=p.active_workspace_id AND user_has_permission(auth.uid(),d.workspace_id,'techsales.deals.'||a||'.workspace')) $$;
CREATE FUNCTION work_record_access(r text,i uuid,a text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM contracts c JOIN profiles p ON p.id=auth.uid() WHERE c.id=CASE WHEN r='techcontracts.approvals' THEN (SELECT contract_id FROM contract_approvals WHERE id=i) ELSE i END AND c.workspace_id=p.active_workspace_id AND user_has_permission(auth.uid(),c.workspace_id,CASE WHEN r='techcontracts.approvals' THEN 'techcontracts.approvals.'||a||'.workspace' ELSE 'techcontracts.contracts.'||a||'.workspace' END)) $$;
CREATE FUNCTION work_area_authorize(r text,a text,i uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE w uuid;BEGIN SELECT active_workspace_id INTO w FROM profiles WHERE id=auth.uid();IF NOT user_has_permission(auth.uid(),w,r||'.'||a||'.workspace') THEN RAISE EXCEPTION 'not allowed';END IF;RETURN w;END $$;
CREATE TABLE sales_resource_catalog(table_name text,resource text,responsibles text[],parent_table text,parent_column text);
INSERT INTO sales_resource_catalog VALUES('activities','techsales.activities',ARRAY['assigned_to','owner_id'],null,null);
CREATE FUNCTION sales_access_context() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT work_access_context() $$;
CREATE FUNCTION sales_context_access(c jsonb,w uuid,r text,a text,s uuid[]) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT user_has_permission(auth.uid(),w,r||'.'||a||'.workspace') $$;
CREATE FUNCTION sales_record_context_access(c jsonb,t text,i uuid,a text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT user_has_permission(auth.uid(),(c->>'workspace')::uuid,'techsales.tasks.'||a||'.workspace') $$;
